package run.ikaros.document;
import java.time.Instant; import java.util.ArrayList; import java.util.List; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; import run.ikaros.resource.api.CreateResourceRequest; import run.ikaros.resource.api.ResourceService; import run.ikaros.resource.api.ResourceType;
@Service public class PersistentDocumentService implements DocumentService{private final ResourceService resources;private final DocumentRepository documents;private final DocumentWorkingCopyRepository copies;private final DocumentRevisionRepository revisions;private final DocumentPublicationRepository publications;public PersistentDocumentService(ResourceService r,DocumentRepository d,DocumentWorkingCopyRepository c,DocumentRevisionRepository v,DocumentPublicationRepository p){resources=r;documents=d;copies=c;revisions=v;publications=p;}
 @Override public Mono<DocumentView> create(UUID o,CreateDocumentRequest r){String locale=r.locale()==null||r.locale().isBlank()?"en-US":r.locale();ResourceType type=r.kind()==DocumentKind.ARTICLE?ResourceType.ARTICLE:ResourceType.DOCUMENT;return resources.create(o,new CreateResourceRequest(type,r.title(),locale)).flatMap(x->{Instant now=Instant.now();return documents.save(new DocumentEntity(null,o,x.id(),r.kind(),null,now,now,null)).flatMap(d->copies.save(new DocumentWorkingCopyEntity(null,d.id(),o,r.content()==null?"":r.content(),"v1",null,now,null)).thenReturn(d));}).map(this::view);}
 @Override public Flux<DocumentView> list(UUID o){return documents.findAllByOwnerIdOrderByUpdatedAtDesc(o).take(100).map(this::view);}@Override public Mono<WorkingCopyView> workingCopy(UUID o,UUID id){return owned(o,id).then(copies.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Working Copy 不存在"))).map(this::copyView));}
 @Override public Mono<WorkingCopyView> updateWorkingCopy(UUID o,UUID id,UpdateWorkingCopyRequest r){return owned(o,id).then(copies.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Working Copy 不存在")))).flatMap(c->{if(version(c.version())!=r.expectedVersion())return Mono.error(new ConflictException("Working Copy 版本冲突"));return copies.save(new DocumentWorkingCopyEntity(c.id(),c.documentId(),c.ownerId(),r.content(),r.contentSchemaVersion(),c.baseRevisionId(),Instant.now(),c.version()));}).map(this::copyView);}
 @Override public Mono<MergeWorkingCopyView> mergeWorkingCopy(UUID o,UUID id,MergeWorkingCopyRequest r){return owned(o,id).then(copies.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Working Copy 不存在")))).map(c->DocumentMergeService.merge(c.content(),r.baseContent(),r.localContent(),r.contentSchemaVersion()==null?c.contentSchemaVersion():r.contentSchemaVersion(),version(c.version())));}
 @Override public Mono<RevisionView> commit(UUID o,UUID id,CommitRevisionRequest r){return owned(o,id).then(copies.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Working Copy 不存在")))).flatMap(c->{if(version(c.version())!=r.expectedVersion())return Mono.error(new ConflictException("Working Copy 版本冲突"));return revisions.findTopByDocumentIdOrderByRevisionNumberDesc(id).map(x->x.revisionNumber()+1).defaultIfEmpty(1L).flatMap(n->revisions.save(new DocumentRevisionEntity(null,id,o,n,r.content(),r.contentSchemaVersion(),Instant.now(),o)).flatMap(v->documents.findById(id).flatMap(d->documents.save(new DocumentEntity(d.id(),d.ownerId(),d.resourceId(),d.kind(),v.id(),d.createdAt(),Instant.now(),d.version()))).then(copies.save(new DocumentWorkingCopyEntity(c.id(),c.documentId(),c.ownerId(),r.content(),r.contentSchemaVersion(),v.id(),Instant.now(),c.version())).thenReturn(v))));}).map(this::revisionView);}
 @Override public Flux<RevisionView> revisions(UUID o,UUID id){return owned(o,id).thenMany(revisions.findAllByDocumentIdOrderByRevisionNumberDesc(id).take(100).map(this::revisionView));}@Override public Mono<RevisionComparisonView> compareRevisions(UUID o,UUID id,long from, long to){return owned(o,id).thenMany(revisions.findAllByDocumentIdOrderByRevisionNumberDesc(id).filter(v->v.revisionNumber()==from||v.revisionNumber()==to).take(2)).collectList().flatMap(found->{DocumentRevisionEntity fromRevision=found.stream().filter(v->v.revisionNumber()==from).findFirst().orElse(null);DocumentRevisionEntity toRevision=found.stream().filter(v->v.revisionNumber()==to).findFirst().orElse(null);if(fromRevision==null||toRevision==null)return Mono.error(new NotFoundException("待对比 Revision 不存在"));return Mono.just(new RevisionComparisonView(from,to,diff(fromRevision.content(),toRevision.content())));});}@Override public Mono<RevisionView> restore(UUID o,UUID id,long n){return owned(o,id).then(revisions.findAllByDocumentIdOrderByRevisionNumberDesc(id).filter(v->v.revisionNumber()==n).next().switchIfEmpty(Mono.error(new NotFoundException("Revision 不存在"))).flatMap(old->revisions.findTopByDocumentIdOrderByRevisionNumberDesc(id).map(last->last.revisionNumber()+1).defaultIfEmpty(1L).flatMap(next->revisions.save(new DocumentRevisionEntity(null,id,o,next,old.content(),old.contentSchemaVersion(),Instant.now(),o))).flatMap(created->documents.findById(id).flatMap(d->documents.save(new DocumentEntity(d.id(),d.ownerId(),d.resourceId(),d.kind(),created.id(),d.createdAt(),Instant.now(),d.version()))).then(copies.findByDocumentId(id).flatMap(c->copies.save(new DocumentWorkingCopyEntity(c.id(),c.documentId(),c.ownerId(),created.content(),created.contentSchemaVersion(),created.id(),Instant.now(),c.version())))).thenReturn(created))).map(this::revisionView));}
 @Override public Mono<DocumentPublicationEntity> publication(UUID o,UUID id){return owned(o,id).then(publications.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Publication 不存在"))));}@Override public Mono<DocumentPublicationEntity> publish(UUID o,UUID id,PublishDocumentRequest r){return owned(o,id).then(revisions.findAllByDocumentIdOrderByRevisionNumberDesc(id).filter(v->v.revisionNumber()==r.revisionNumber()).next().switchIfEmpty(Mono.error(new NotFoundException("Revision 不存在")))).flatMap(v->publications.findByDocumentId(id).flatMap(p->publications.save(new DocumentPublicationEntity(p.id(),id,v.id(),r.slug(),DocumentPublicationState.PUBLISHED,Instant.now(),p.version()))).switchIfEmpty(publications.save(new DocumentPublicationEntity(null,id,v.id(),r.slug(),DocumentPublicationState.PUBLISHED,Instant.now(),null))));}@Override public Mono<DocumentPublicationEntity> unpublish(UUID o,UUID id){return owned(o,id).then(publications.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Publication 不存在"))).flatMap(p->publications.save(new DocumentPublicationEntity(p.id(),p.documentId(),p.revisionId(),p.slug(),DocumentPublicationState.UNPUBLISHED,p.publishedAt(),p.version()))));}
 private Mono<DocumentEntity> owned(UUID o,UUID id){return documents.findById(id).filter(d->d.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Document 不存在或无权访问")));}private List<RevisionDiffLine> diff(String from,String to){String[] left=(from==null?"":from).split("\\R",-1);String[] right=(to==null?"":to).split("\\R",-1);List<RevisionDiffLine> lines=new ArrayList<>();int index=0;while(index<left.length||index<right.length){if(index<left.length&&index<right.length&&left[index].equals(right[index]))lines.add(new RevisionDiffLine("UNCHANGED",left[index]));else{if(index<left.length)lines.add(new RevisionDiffLine("REMOVED",left[index]));if(index<right.length)lines.add(new RevisionDiffLine("ADDED",right[index]));}index++;}return lines;}private long version(Long v){return v==null?0:v;}private DocumentView view(DocumentEntity d){return new DocumentView(d.id(),d.resourceId(),d.kind(),d.currentRevisionId());}private WorkingCopyView copyView(DocumentWorkingCopyEntity c){return new WorkingCopyView(c.documentId(),c.content(),c.contentSchemaVersion(),c.baseRevisionId(),c.updatedAt(),version(c.version()));}private RevisionView revisionView(DocumentRevisionEntity r){return new RevisionView(r.id(),r.documentId(),r.revisionNumber(),r.content(),r.contentSchemaVersion(),r.createdAt());}}
